using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class AbilityEffectsTests
{
 static readonly EntityId Actor=new("created:ability-worker"),Issuer=new("person:nobunaga"),Job=new("job:ability");
 internal static WorldSession Start(int politics=80,int negotiation=80,int intelligence=80){var officer=NewGameWorldTests.Officer(Actor.Value,StartTemplate.Retainer,lord:Issuer.Value) with{Attributes=new(60,60,intelligence,politics){Negotiation=negotiation}};var setup=NewGameWorldTests.Setup([officer]);return new(NewGameWorld.Create(setup.World,setup.Registered,Actor.Value,42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy,developmentPolicy:CharacterDevelopment.Policy,abilityPolicy:AbilityEffects.Policy));}
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 static void Accept(WorldSession s)=>Good(s.ManageBroker(new(Job,BrokerAction.Accept,Issuer:Issuer,Kind:BrokerKind.Purchase),s.Revision));
 static void Finish(WorldSession s){foreach(var action in new[]{BrokerAction.Buy,BrokerAction.Deliver,BrokerAction.Settle})Good(s.ManageBroker(new(new("request:ability/"+action),action,Job),s.Revision));}
 [Fact]public void PoliticsChangesPreparationAndNegotiationChangesRealEscrow(){var high=Start();var low=Start(20,20);Accept(high);Accept(low);var a=BrokerWork.Jobs(high.DiagnosticSnapshot()).Single().Terms;var b=BrokerWork.Jobs(low.DiagnosticSnapshot()).Single().Terms;Assert.True(a.Abilities!.ReadyAt<b.Abilities!.ReadyAt);Assert.Equal(b.Fee+10,a.Fee);Assert.Equal(ResultCode.NotAvailable,high.ManageBroker(new(new("request:too-early"),BrokerAction.Buy,Job),high.Revision).Code);NewGameWorldTests.At(high,a.Abilities.ReadyAt);NewGameWorldTests.At(low,b.Abilities.ReadyAt);Finish(high);Finish(low);Assert.Equal(1060,NewGameWork.Balance(high.DiagnosticSnapshot(),Actor));Assert.Equal(1050,NewGameWork.Balance(low.DiagnosticSnapshot(),Actor));}
 [Fact]public void MidPreparationRealSavePreservesTermsAndSettlement(){var s=Start();Accept(s);NewGameWorldTests.At(s,100);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"ability-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"mid",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("mid"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current}){NewGameWorldTests.At(x,1000);Finish(x);}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
 [Fact]public void IntelligenceAddsLocalObservationWithoutInventingBlockCause(){var high=Start();var low=Start(intelligence:20);foreach(var s in new[]{high,low}){Good(s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:ability-inspect"),s.Revision));NewGameWorldTests.At(s,8);}Assert.Single(AbilityEffects.KnownInspection(high,Actor));Assert.Empty(AbilityEffects.KnownInspection(low,Actor));Assert.Contains("原因は未確認",AbilityEffects.KnownInspection(high,Actor).Single());}
 [Fact]public void OldWorldHasNoNewPreparationAndRoundTrips(){var s=BrokerWorkTests.Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));Accept(s);Assert.Null(BrokerWork.Jobs(s.DiagnosticSnapshot()).Single().Terms.Abilities);}
 [Fact]public void ExtraObservationRequiresDeliveredOpenedReport(){var s=Start();Good(s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:ability-report"),s.Revision));NewGameWorldTests.At(s,1);var task=s.DiagnosticSnapshot().Tasks.Last();var message=s.GetActorView(Actor).Messages.Single(m=>m.KnownBody==null);Good(s.Open(Actor,message.Id,s.Revision));if(task.Kind==TaskKind.VoluntaryRequest)Good(s.Assent(task.Id,Actor,true,s.Revision));NewGameWorldTests.At(s,8);var note=s.DiagnosticSnapshot().Outbox.Single(o=>o.Kind=="inspection-detail");Assert.Empty(AbilityEffects.KnownInspection(s,note.Recipient));Good(s.Open(note.Recipient,note.Id,s.Revision));Assert.Single(AbilityEffects.KnownInspection(s,note.Recipient));}
}
